const raw = String($json.Brands ?? $json.brands ?? '').trim();

if (!raw) {
  throw new Error('Brands list is empty');
}

const lines = raw
  .split(/\r?\n/)
  .map(s => s.trim())
  .filter(Boolean);

const valid = [];
const invalid = [];

for (const line of lines) {
  const parts = line.split('|').map(s => s.trim());
  if (parts.length !== 3 || !parts[0] || !parts[1] || !parts[2]) {
    invalid.push(line);
    continue;
  }
  valid.push(parts.join('|'));
}

if (!valid.length) {
  throw new Error('No valid rows. Use: Brand|domain|country');
}

if (invalid.length) {
  throw new Error('Invalid rows: ' + invalid.join(' ; '));
}

return [{
  json: {
    brandCount: valid.length,
    brandsText: valid.join('\n'),
    inputBase64: Buffer.from(valid.join('\n'), 'utf8').toString('base64')
  }
}];

const raw = $json.stdout;

if (!raw) {
  throw new Error('Serper search returned empty stdout');
}

const data = JSON.parse(raw);

return [{
  json: {
    generatedAt: data.generatedAt,
    brandCount: data.searches?.length ?? 0,
    totalUrls: (data.searches ?? []).reduce((sum, x) => sum + (x.results?.length ?? 0), 0),
    searches: data.searches ?? [],
    failures: data.failures ?? []
  }
}];
